  ('lsec-eng-014', 1, 'in_review', array['lower_secondary']::text[], 'english', 'Vocabulary', 'Word relationships', 1, 'remember', 'fill_blank', 'A word that has the same or nearly the same meaning as another word is called a ___.', null, null, 'Know the terms synonym and antonym.', 'Lower secondary English: vocabulary (e.g. KSSM Bahasa Inggeris).', '{"system":"KSSM","subject":"Bahasa Inggeris","years":[1,2,3]}'::jsonb, 'Eduventure (original questions)', 'CC BY 4.0'),
  ('lsec-eng-015', 1, 'in_review', array['lower_secondary']::text[], 'english', 'Sentences', 'Complex sentences', 3, 'analyze', 'mcq', 'Which of these is a complex sentence?', '[{"id":"a","text":"We went out."},{"id":"b","text":"It was raining, but we went out."},{"id":"c","text":"Although it was raining, we went out."},{"id":"d","text":"Because of the rain."}]'::jsonb, null, 'Identify simple, compound and complex sentences.', 'Lower secondary English: sentence structure (e.g. KSSM Bahasa Inggeris / CEFR B1).', '{"system":"KSSM","subject":"Bahasa Inggeris","years":[1,2,3]}'::jsonb, 'Eduventure (original questions)', 'CC BY 4.0'),
  ('lsec-geo-001', 1, 'in_review', array['lower_secondary']::text[], 'geography', 'Map skills', 'Latitude', 1, 'remember', 'mcq', 'What is the latitude of the Equator?', '[{"id":"a","text":"0°"},{"id":"b","text":"90°"},{"id":"c","text":"180°"},{"id":"d","text":"23.5°"}]'::jsonb, null, 'Use latitude to describe location.', 'Lower secondary geography: map skills (e.g. KSSM Geografi Tingkatan 1).', '{"system":"KSSM","subject":"Geografi","years":[1]}'::jsonb, 'Eduventure (original questions)', 'CC BY 4.0'),
  ('lsec-geo-002', 1, 'in_review', array['lower_secondary']::text[], 'geography', 'Malaysia', 'Famous places', 2, 'remember', 'matching', 'Match each place to the Malaysian state it is in.', '{"left":[{"id":"a","text":"Mount Kinabalu"},{"id":"b","text":"Gunung Mulu National Park"},{"id":"c","text":"George Town"}],"right":[{"id":"x","text":"Penang"},{"id":"y","text":"Sabah"},{"id":"z","text":"Sarawak"}]}'::jsonb, null, 'Locate key places in Malaysia.', 'Lower secondary geography: Malaysia (e.g. KSSM Geografi Tingkatan 1–3).', '{"system":"KSSM","subject":"Geografi","years":[1,2,3]}'::jsonb, 'Eduventure (original questions)', 'CC BY 4.0'),
  ('lsec-geo-003', 1, 'in_review', array['lower_secondary']::text[], 'geography', 'Malaysia', 'Rivers', 3, 'remember', 'mcq', 'Which is the longest river in Malaysia?', '[{"id":"a","text":"Pahang River"},{"id":"b","text":"Rajang River"},{"id":"c","text":"Kinabatangan River"},{"id":"d","text":"Perak River"}]'::jsonb, null, 'Describe major physical features of Malaysia.', 'Lower secondary geography: rivers (e.g. KSSM Geografi Tingkatan 1–2).', '{"system":"KSSM","subject":"Geografi","years":[1,2]}'::jsonb, 'Eduventure (original questions)', 'CC BY 4.0'),
  ('lsec-geo-004', 1, 'in_review', array['lower_secondary']::text[], 'geography', 'Map skills', 'Malaysia''s position', 2, 'understand', 'true_false', 'True or false: the Equator passes through Malaysia.', null, null, 'Describe Malaysia''s position using latitude.', 'Lower secondary geography: location of Malaysia (e.g. KSSM Geografi Tingkatan 1).', '{"system":"KSSM","subject":"Geografi","years":[1]}'::jsonb, 'Eduventure (original questions)', 'CC BY 4.0'),
  ('lsec-geo-005', 1, 'in_review', array['lower_secondary']::text[], 'geography', 'World', 'Continents', 2, 'remember', 'ordering', 'Put these continents in order of land area, from largest to smallest.', '[{"id":"a","text":"Europe"},{"id":"b","text":"Asia"},{"id":"c","text":"Australia"},{"id":"d","text":"Africa"}]'::jsonb, null, 'Compare the sizes of the continents.', 'Lower secondary geography: the world (e.g. KSSM Geografi Tingkatan 1).', '{"system":"KSSM","subject":"Geografi","years":[1]}'::jsonb, 'Eduventure (original questions)', 'CC BY 4.0')
insert into public.question_keys (question_id, answer, explanation, wrong, mistakes) values
  ('lsec-math-016', '"b"'::jsonb, 'Factors of 24: 1, 2, 3, 4, 6, 8, 12, 24. Factors of 36: 1, 2, 3, 4, 6, 9, 12, 18, 36. The largest one in both lists is 12.', '{"a":"6 is a common factor, but not the highest: 12 also divides both.","c":"72 is the lowest common multiple, not a factor.","d":"4 is a common factor, but 12 is bigger."}'::jsonb, null),
  ('lsec-math-017', '{"value":24,"tolerance":0}'::jsonb, 'Multiples of 6: 6, 12, 18, 24 … Multiples of 8: 8, 16, 24 … The first number in both lists is 24.', null, '[{"value":48,"why":"48 is 6 × 8, a common multiple but not the lowest."},{"value":2,"why":"2 is the highest common factor, not the lowest common multiple."}]'::jsonb),
  ('lsec-math-018', '{"value":6,"tolerance":0}'::jsonb, 'Add 7 to both sides: 3x = 18. Divide both sides by 3: x = 6. Check: 3 × 6 − 7 = 11.', null, '[{"value":4,"why":"That comes from 3x = 11 − 7; undo the − 7 by adding 7, not subtracting."}]'::jsonb),
  ('lsec-math-019', '"b"'::jsonb, 'Multiply every term inside the bracket by 4: 4 × 2x = 8x and 4 × (−3) = −12.', '{"a":"The 4 must multiply the −3 as well: 4 × (−3) = −12.","c":"4 × (−3) is negative: −12, not +12.","d":"This adds 4 instead of multiplying by 4."}'::jsonb, null),
  ('lsec-math-020', '{"value":-4,"tolerance":0}'::jsonb, '24 ÷ 6 = 4, and a negative divided by a positive is negative, so the answer is −4.', null, '[{"value":4,"why":"Check the sign: negative ÷ positive gives a negative answer."}]'::jsonb),
  ('lsec-math-021', '["a","c","d"]'::jsonb, 'A rational number can be written as a fraction of two integers: 0.5 = 1/2, −3 = −3/1 and 2/7 already is one.', '{"b":"√2 cannot be written as a fraction of integers; its decimal never ends or repeats.","e":"π is irrational: 22/7 and 3.14 are only approximations."}'::jsonb, null),
  ('lsec-math-022', '["d","b","c","a"]'::jsonb, 'Write them as decimals: −1, −0.5, 0.25, 0.3. The further left on the number line, the smaller.', null, null),
  ('lsec-math-023', '{"value":720,"tolerance":0,"unit":"°"}'::jsonb, 'Sum of interior angles = (n − 2) × 180°. A hexagon has 6 sides: (6 − 2) × 180° = 720°.', null, '[{"value":1080,"why":"That is 6 × 180°; use (n − 2) × 180°."},{"value":360,"why":"360° is the sum of the exterior angles of any polygon."}]'::jsonb),
  ('lsec-math-024', '"a"'::jsonb, 'The exterior angles of any polygon add up to 360°. A regular octagon has 8 equal ones: 360° ÷ 8 = 45°.', '{"b":"135° is each interior angle (180° − 45°).","c":"60° is the exterior angle of a regular hexagon.","d":"360° is the total of all eight exterior angles."}'::jsonb, null),
  ('lsec-math-025', '{"value":60,"tolerance":0,"unit":"cm³"}'::jsonb, 'Volume = length × width × height = 5 × 4 × 3 = 60 cm³.', null, '[{"value":12,"why":"12 adds the three lengths; volume multiplies them."},{"value":94,"why":"94 cm² is the surface area, not the volume."}]'::jsonb),
  ('lsec-math-026', '"a"'::jsonb, 'When multiplying powers of the same base, add the indices: a³ × a⁴ = a³⁺⁴ = a⁷.', '{"b":"Multiply the indices only when raising a power to a power, (a³)⁴ = a¹².","c":"There is only one a⁷: 1 × 1 = 1, so no 2 in front.","d":"Subtracting indices is for division, and 4 − 3 would give a, not this product."}'::jsonb, null),
  ('lsec-math-027', '"b"'::jsonb, 'Move the decimal point 4 places right to get 4.5, so 0.00045 = 4.5 × 10⁻⁴. Numbers smaller than 1 have a negative power.', '{"a":"10⁴ makes 45,000; a number smaller than 1 needs a negative power.","c":"This equals 0.00045, but standard form needs a number from 1 to less than 10 in front.","d":"10⁻³ gives 0.0045, ten times too big."}'::jsonb, null),
  ('lsec-math-028', '{"a":"y","b":"z","c":"x"}'::jsonb, 'Mode = most often (think "most"). Median = middle (like the median strip in the middle of a road). Range = largest − smallest.', null, null),
  ('lsec-math-029', '"a"'::jsonb, 'Probability = favourable outcomes ÷ all outcomes = 3 red ÷ 8 marbles = 3/8.', '{"b":"3/5 compares red to blue; divide by all 8 marbles instead.","c":"5/8 is the probability of blue.","d":"1/3 does not use the numbers of marbles at all."}'::jsonb, null),
  ('lsec-math-030', '{"value":300,"tolerance":0,"unit":"RM"}'::jsonb, 'Simple interest = principal × rate × time = 2,000 × 0.05 × 3 = RM300.', null, '[{"value":100,"why":"RM100 is one year''s interest; multiply by 3 years."},{"value":2300,"why":"RM2,300 is the total in the account; the question asks only for the interest."}]'::jsonb),
  ('lsec-math-031', '{"accept":["decagon"]}'::jsonb, 'A 10-sided polygon is a decagon ("deca" means ten, as in decade: ten years).', null, null),
  ('lsec-math-032', '"true"'::jsonb, 'Each diagonal is the hypotenuse of a right-angled triangle with the same two sides (length and width), so both diagonals are equal.', '{"false":"Draw both diagonals: each one splits the rectangle into identical right-angled triangles, so they must be the same length."}'::jsonb, null),
  ('lsec-math-033', '"b"'::jsonb, 'x² − 9 = x² − 3² is a difference of two squares: a² − b² = (a + b)(a − b), so x² − 9 = (x + 3)(x − 3).', '{"a":"(x − 3)² = x² − 6x + 9, which has an extra −6x and +9.","c":"(x + 3)² = x² + 6x + 9.","d":"(x − 9)(x + 1) = x² − 8x − 9."}'::jsonb, null),
  ('lsec-math-034', '{"value":2,"tolerance":0,"unit":"km"}'::jsonb, '4 cm × 50,000 = 200,000 cm. There are 100,000 cm in 1 km, so 200,000 cm = 2 km.', null, '[{"value":200,"why":"200,000 cm is 2,000 m, which is 2 km, not 200 km. Check the unit conversion."},{"value":20,"why":"Check the conversion: 100 cm = 1 m and 1,000 m = 1 km, so 100,000 cm = 1 km."}]'::jsonb),
  ('lsec-math-035', '["a","b"]'::jsonb, '4 × 4 = 16 and (−4) × (−4) = 16, so both 4 and −4 work.', '{"c":"8² = 64, not 16. (8 is 16 ÷ 2.)","d":"16² = 256.","e":"(−8)² = 64."}'::jsonb, null),
  ('lsec-sci-011', '"b"'::jsonb, 'Chloroplasts contain chlorophyll for photosynthesis. Animal cells do not make their own food, so they have none. (Plant cells also have a cell wall.)', '{"a":"Both plant and animal cells have a nucleus.","c":"Both have a cell membrane.","d":"Both have mitochondria for respiration."}'::jsonb, null),
  ('lsec-sci-012', '["b","d","a","c"]'::jsonb, 'Cells group into tissues, tissues form organs, and organs work together in systems (e.g. muscle cells → muscle tissue → heart → circulatory system).', null, null),
  ('lsec-sci-013', '{"a":"z","b":"x","c":"y"}'::jsonb, 'Solids keep their shape because particles are fixed in place. Liquids flow because particles can slide. Gases spread out because particles move freely.', null, null),
  ('lsec-sci-014', '{"value":4,"tolerance":0,"unit":"g/cm³"}'::jsonb, 'Density = mass ÷ volume = 200 ÷ 50 = 4 g/cm³.', null, '[{"value":0.25,"why":"That is volume ÷ mass; density is mass ÷ volume."},{"value":10000,"why":"Density divides mass by volume; it does not multiply them."}]'::jsonb),
  ('lsec-sci-015', '"b"'::jsonb, 'Burning makes new substances (ash, carbon dioxide, water vapour) and cannot easily be reversed. That makes it a chemical change.', '{"a":"Melting only changes the state; freezing turns it back into ice.","c":"The sugar is still sugar; evaporating the water gets it back.","d":"Cutting changes the shape, not the substance."}'::jsonb, null),
  ('lsec-sci-016', '["a","c","e"]'::jsonb, 'Copper, iron and magnesium are metals: shiny, good conductors of heat and electricity.', '{"b":"Sulphur is a yellow, brittle non-metal that does not conduct electricity.","d":"Carbon is a non-metal (graphite conducts electricity, but carbon is still classed as a non-metal)."}'::jsonb, null),
  ('lsec-sci-017', '"false"'::jsonb, 'Sound is a vibration passed from particle to particle. A vacuum has no particles, so sound cannot travel through it. That is why space is silent.', '{"true":"Sound needs a medium (solid, liquid or gas) to carry its vibrations; light can cross a vacuum, sound cannot."}'::jsonb, null),
  ('lsec-sci-018', '{"value":12,"tolerance":0,"unit":"V"}'::jsonb, 'Ohm''s law: V = I × R = 2 × 6 = 12 V.', null, '[{"value":3,"why":"That is R ÷ I; voltage is current × resistance."},{"value":8,"why":"Ohm''s law multiplies current and resistance; it does not add them."}]'::jsonb),
  ('lsec-sci-019', '"a"'::jsonb, 'Arteries carry blood away from the heart under high pressure, so they have thick, muscular walls. (A for Arteries, A for Away.)', '{"b":"Veins carry blood back to the heart.","c":"Capillaries are tiny vessels where substances pass between blood and cells.","d":"Valves are flaps that stop blood flowing backwards; they are not vessels."}'::jsonb, null),
  ('lsec-sci-020', '{"accept":["evaporation","evaporating"]}'::jsonb, 'Evaporation happens at the surface at any temperature, like a puddle drying in the sun. Boiling happens throughout the liquid at the boiling point.', null, null),
  ('lsec-sci-021', '"a"'::jsonb, 'The crust is the thin, solid outer layer of the Earth. Everything we stand on is part of it.', '{"b":"The mantle lies under the crust and is made of hot, slowly flowing rock.","c":"The outer core is liquid metal deep below the mantle.","d":"The inner core is the solid metal centre of the Earth."}'::jsonb, null),
  ('lsec-sci-022', '["b","d","a","c"]'::jsonb, 'Grass (producer) is eaten by the grasshopper, which is eaten by the frog, which is eaten by the snake. Energy flows along the chain.', null, null),
  ('lsec-sci-023', '"a"'::jsonb, 'Carbohydrates (rice, bread, noodles) are broken down into glucose, which cells use for energy.', '{"b":"Vitamins are needed in small amounts to keep the body healthy, but give no energy.","c":"Minerals (like calcium and iron) build bones and blood; they give no energy.","d":"Fibre helps digestion; we cannot digest it for energy."}'::jsonb, null),
  ('lsec-sci-024', '{"value":50,"tolerance":0,"unit":"J"}'::jsonb, 'Work done = force × distance moved in the direction of the force = 10 N × 5 m = 50 J.', null, '[{"value":2,"why":"That divides force by distance; work multiplies them."},{"value":15,"why":"Work multiplies force and distance; it does not add them."}]'::jsonb),
  ('lsec-sci-025', '["a","c","e"]'::jsonb, 'Coal, natural gas and petroleum are fossil fuels. They took millions of years to form and will run out.', '{"b":"Sunlight keeps arriving every day, so solar energy is renewable.","d":"Wind keeps blowing, so wind energy is renewable."}'::jsonb, null),
  ('lsec-eng-006', '"a"'::jsonb, 'For a real possibility in the future (first conditional): If + present simple, will + verb. If it rains, we will stay.', '{"b":"\"Would\" goes with imagined situations: If it rained, we would stay.","c":"\"Had stay\" is not correct English.","d":"\"Are stay\" is not correct; \"stay\" needs \"will\" here."}'::jsonb, null),
  ('lsec-eng-007', '["a","c","d"]'::jsonb, 'Conjunctions join words or clauses: and (adds), but (contrasts), because (gives a reason).', '{"b":"\"Quickly\" is an adverb: it describes how something is done.","e":"\"Table\" is a noun: it names a thing."}'::jsonb, null),
  ('lsec-eng-008', '["b","c","d","a","e"]'::jsonb, 'Present perfect questions: Have + subject + (ever) + past participle: Have you ever been to Sabah?', null, null),
  ('lsec-eng-009', '{"a":"y","b":"z","c":"x"}'::jsonb, 'A simile compares using "as" or "like". A metaphor says one thing is another. Personification gives human actions (whispering) to non-human things.', null, null),
  ('lsec-eng-010', '{"accept":["written"]}'::jsonb, '"Write" is irregular: write → wrote → written. She has written three letters.', null, null),
  ('lsec-eng-011', '"a"'::jsonb, 'If you are reluctant, you do not want to do something: you are unwilling. "He was reluctant to leave the party."', '{"b":"\"Eager\" is almost the opposite: keen to do something.","c":"\"Curious\" means wanting to know about something.","d":"\"Tired\" describes needing rest, not unwillingness."}'::jsonb, null),
  ('lsec-eng-012', '"false"'::jsonb, 'The second word should be "their" (belonging to them): They''re going to bring their books. "There" is for places.', '{"true":"\"There\" means a place (over there). For something belonging to them, use \"their\"."}'::jsonb, null),
  ('lsec-eng-013', '"b"'::jsonb, 'The present perfect is has/have + past participle: she has finished.', '{"a":"This is the simple past.","c":"This is the present continuous.","d":"This is the simple future."}'::jsonb, null),
  ('lsec-eng-014', '{"accept":["synonym"]}'::jsonb, 'Synonyms share a meaning (big – large). Words with opposite meanings are antonyms (big – small).', null, null),
  ('lsec-eng-015', '"c"'::jsonb, 'A complex sentence has a main clause and a dependent clause, often starting with a word like although, because or when.', '{"a":"This is a simple sentence: one main clause.","b":"This is a compound sentence: two main clauses joined by \"but\".","d":"This is a fragment: it has no main verb and cannot stand alone."}'::jsonb, null),
  ('lsec-geo-001', '"a"'::jsonb, 'The Equator is the 0° line of latitude, halfway between the North and South Poles.', '{"b":"90° north and south are the Poles.","c":"180° is a line of longitude (opposite the Prime Meridian), not latitude.","d":"About 23.5° north and south are the Tropics of Cancer and Capricorn."}'::jsonb, null),
  ('lsec-geo-002', '{"a":"y","b":"z","c":"x"}'::jsonb, 'Mount Kinabalu is in Sabah, Gunung Mulu National Park (famous for its caves) is in Sarawak, and George Town is the capital of Penang.', null, null),
  ('lsec-geo-003', '"b"'::jsonb, 'The Rajang River in Sarawak, about 560 km long, is Malaysia''s longest river.', '{"a":"The Pahang River is the longest in Peninsular Malaysia, but shorter than the Rajang.","c":"The Kinabatangan in Sabah is the second longest.","d":"The Perak River is shorter than both the Rajang and the Pahang."}'::jsonb, null),
  ('lsec-geo-004', '"false"'::jsonb, 'All of Malaysia lies a little north of the Equator, between about 1°N and 7°N. The Equator passes through neighbouring Indonesia.', '{"true":"Malaysia is close to the Equator, which is why it is hot all year, but every part of it is north of the line."}'::jsonb, null),
  ('lsec-geo-005', '["b","d","a","c"]'::jsonb, 'Asia is the largest continent, then Africa. Europe is bigger than Australia, which is the smallest continent.', null, null)
